mapper.select:
SELECT receipt_id, user_id, object_key, bucket_name, file_url, file_name, content_type, file_size, status, total_amount, created_at, updated_at, reference_id, total_amount_paid, total_tax_amount FROM receipt
AND user_id = #{userId}
AND receipt_id = #{receiptId}::uuid
ORDER BY created_at DESC LIMIT #{pageSize} OFFSET #{pageNo}
